import { FormEvent, type ReactNode, useState } from 'react';
import { Link, useLocation, useParams } from 'wouter';
import { ArrowRight, BadgeCheck, BarChart3, BriefcaseBusiness, CalendarDays, Check, CheckCircle2, ChevronRight, CircleHelp, Clock3, FileText, Filter, Flag, Heart, House, ImagePlus, IndianRupee, Laptop, LockKeyhole, MapPin, MessageCircle, MoreHorizontal, Paperclip, Pencil, Plus, Search, Send, ShieldAlert, ShieldCheck, SlidersHorizontal, Sparkles, Star, Tag, Upload, Users, WalletCards } from 'lucide-react';
import { Avatar, Badge, Button, Logo, PageIntro, StatCard } from '@/components/AppShell';
import { categories, jobs, messages, type Job, type Mode, workers } from '@/lib/mock-data';

function SectionCard({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-5 shadow-[0_10px_30px_hsl(198_30%_16%/.04)] ${className}`}>{children}</section>; }
function Rating({ value, reviews }: { value: number; reviews?: number }) { return <span className="inline-flex items-center gap-1 text-xs font-bold"><Star size={13} className="fill-[#e3a91b] text-[#e3a91b]" /> {value} {reviews !== undefined && <span className="font-normal text-[hsl(var(--muted-foreground))]">({reviews})</span>}</span>; }
function EmptyState({ icon: Icon = Search, title, copy, href, cta }: { icon?: typeof Search; title: string; copy: string; href?: string; cta?: string }) { return <div className="grid place-items-center rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.5)] px-6 py-16 text-center"><span className="mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><Icon size={22} /></span><h3 className="text-lg font-bold">{title}</h3><p className="mt-2 max-w-sm text-sm text-[hsl(var(--muted-foreground))]">{copy}</p>{href && <Button href={href} className="mt-5">{cta}</Button>}</div>; }

export function Home({ mode }: { mode: Mode }) {
  const [search, setSearch] = useState('');
  const [saved, setSaved] = useState<string[]>([]);
  return <div className="rise-in">
    <div className="relative overflow-hidden rounded-[2rem] bg-[hsl(var(--sidebar))] px-6 py-9 text-[hsl(var(--sidebar-foreground))] sm:px-12 sm:py-14">
      <div className="absolute -right-12 -top-24 h-72 w-72 rounded-full border-[32px] border-[hsl(var(--secondary)/.85)] opacity-80" /><div className="absolute -bottom-28 right-48 h-52 w-52 rounded-full bg-[hsl(var(--accent)/.38)] blur-2xl" />
      <div className="relative max-w-2xl"><Badge tone="yellow">The neighborhood network for getting things done</Badge><h1 className="display-font mt-6 text-4xl font-bold leading-[.98] tracking-tight sm:text-6xl">Good work is closer<br /><span className="text-[hsl(var(--secondary))]">than you think.</span></h1><p className="mt-5 max-w-lg text-base leading-7 text-[hsl(var(--sidebar-foreground)/.68)]">Hire a trusted local hand or find your next client — from a leaking tap to the launch video that makes your idea click.</p>
        <div className="mt-8 flex max-w-xl flex-col gap-2 rounded-2xl bg-[hsl(var(--background))] p-2 sm:flex-row"><div className="flex flex-1 items-center gap-3 px-3"><Search size={19} className="text-[hsl(var(--muted-foreground))]" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="What do you need help with?" className="w-full bg-transparent py-3 text-sm text-[hsl(var(--foreground))] outline-none" data-testid="input-home-search" /></div><Button href={`/services${search ? `?q=${search}` : ''}`} variant="secondary" testId="button-search-home">Find the right person <ArrowRight size={16} /></Button></div>
        <div className="mt-5 flex flex-wrap gap-x-5 gap-y-2 text-xs text-[hsl(var(--sidebar-foreground)/.6)]"><span className="flex items-center gap-1.5"><ShieldCheck size={14} className="text-[hsl(var(--secondary))]" /> Verified profiles</span><span className="flex items-center gap-1.5"><LockKeyhole size={14} className="text-[hsl(var(--secondary))]" /> Safe payments</span><span className="flex items-center gap-1.5"><Flag size={14} className="text-[hsl(var(--secondary))]" /> Humans who care</span></div>
      </div>
    </div>
    <div className="mt-10 flex items-end justify-between"><div><p className="mono text-[10px] font-bold uppercase tracking-[.2em] text-[hsl(var(--primary))]">A good place to start</p><h2 className="mt-2 text-2xl font-bold">Popular near you</h2></div><Link href="/services" className="hidden items-center gap-1 text-sm font-bold text-[hsl(var(--primary))] sm:flex" data-testid="link-all-services">See all services <ArrowRight size={15} /></Link></div>
    <div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{workers.slice(0, 4).map((worker, i) => <SectionCard key={worker.id} className={`group relative overflow-hidden p-0 ${i === 1 ? 'lg:translate-y-4' : ''}`}><div className={`h-24 ${worker.color}`}><div className="absolute right-4 top-4"><button onClick={() => setSaved(prev => prev.includes(worker.id) ? prev.filter(id => id !== worker.id) : [...prev, worker.id])} className="grid h-8 w-8 place-items-center rounded-full bg-[hsl(var(--card)/.8)]" data-testid={`button-save-worker-${worker.id}`}><Heart size={15} className={saved.includes(worker.id) ? 'fill-[hsl(var(--accent))] text-[hsl(var(--accent))]' : ''} /></button></div></div><div className="-mt-7 px-4 pb-4"><Avatar initials={worker.initials} color={worker.color} size="lg" /><div className="mt-3 flex items-start justify-between gap-2"><div><Link href={`/worker/${worker.id}`} className="font-bold hover:text-[hsl(var(--primary))]" data-testid={`link-worker-${worker.id}`}>{worker.name}</Link><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{worker.service}</p></div><Rating value={worker.rating} /></div><div className="mt-4 flex items-center justify-between text-xs"><span className="flex items-center gap-1 text-[hsl(var(--muted-foreground))]"><MapPin size={13} />{worker.distance}</span><span className="font-bold">{worker.price}</span></div></div></SectionCard>)}</div>
    <div className="mt-14 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><SectionCard className="paper-grid flex min-h-[240px] flex-col justify-between overflow-hidden bg-[hsl(var(--secondary)/.3)]"><div><Badge tone="green">For customers</Badge><h2 className="mt-4 max-w-md text-3xl font-bold">Post once.<br />Get the right help.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">Tell us what needs doing and let local pros come to you. No awkward cold calls.</p></div><Button href="/post-job" className="mt-6 w-fit">Post a job <Plus size={15} /></Button></SectionCard><SectionCard className="bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))]"><Badge>For independent workers</Badge><h2 className="mt-4 text-3xl font-bold">Your skills<br />have a market.</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--accent-foreground)/.75)]">Build a profile that feels like you, find fair work, and keep 90% of what you earn.</p><Button href="/work" variant="secondary" className="mt-6 w-fit">Browse open work <ArrowRight size={15} /></Button></SectionCard></div>
    <div className="mt-14 border-t border-[hsl(var(--border))] pt-8"><div className="flex items-center gap-2"><Sparkles size={17} className="text-[hsl(var(--accent))]" /><h2 className="text-xl font-bold">How matching works</h2></div><div className="mt-5 grid gap-3 sm:grid-cols-4">{[['40%', 'Skill fit'], ['20%', 'Distance'], ['15%', 'Rating'], ['15%', 'Availability']].map(([n, label]) => <div key={label} className="flex items-center gap-3 rounded-xl bg-[hsl(var(--muted)/.55)] p-4"><span className="display-font text-xl font-bold text-[hsl(var(--primary))]">{n}</span><span className="text-sm font-semibold">{label}</span></div>)}</div><p className="mt-3 text-xs text-[hsl(var(--muted-foreground))]">Experience adds the final 10%. Clear signals, no mystery ranking.</p></div>
  </div>;
}

export function Services() {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('All categories'); const [remote, setRemote] = useState('Any'); const [favorites, setFavorites] = useState<string[]>([]);
  const filtered = workers.filter(w => (!query || `${w.name} ${w.service} ${w.skills.join(' ')}`.toLowerCase().includes(query.toLowerCase())) && (category === 'All categories' || w.service === category) && (remote === 'Any' || (remote === 'Remote' ? w.remote : !w.remote)));
  return <div className="rise-in"><PageIntro eyebrow="Marketplace / services" title="Find someone good at this." description="Local hands, digital minds, and people who take pride in a job done properly." action={<Button href="/post-job" variant="secondary"><Plus size={16} /> Post a job</Button>} />
    <SectionCard className="mb-6 p-3"><div className="grid gap-2 md:grid-cols-[1.5fr_1fr_1fr_auto]"><label className="flex items-center gap-2 rounded-xl bg-[hsl(var(--muted)/.6)] px-3"><Search size={17} className="text-[hsl(var(--muted-foreground))]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search a skill, name, or service" className="w-full bg-transparent py-3 text-sm outline-none" data-testid="input-service-search" /></label><select value={category} onChange={e => setCategory(e.target.value)} className="rounded-xl bg-[hsl(var(--muted)/.6)] px-3 py-3 text-sm outline-none" data-testid="select-service-category"><option>All categories</option>{categories.map(c => <option key={c}>{c}</option>)}</select><select value={remote} onChange={e => setRemote(e.target.value)} className="rounded-xl bg-[hsl(var(--muted)/.6)] px-3 py-3 text-sm outline-none" data-testid="select-service-mode"><option>Any</option><option>Local</option><option>Remote</option></select><Button variant="ghost" onClick={() => { setQuery(''); setCategory('All categories'); setRemote('Any'); }}><SlidersHorizontal size={16} /> Clear</Button></div><div className="mt-3 flex flex-wrap gap-2 px-1 text-xs text-[hsl(var(--muted-foreground))]"><span className="flex items-center gap-1"><MapPin size={13} /> Bengaluru, 10 km</span><span className="flex items-center gap-1"><Star size={13} /> 4.5+ rating</span><span className="flex items-center gap-1"><CalendarDays size={13} /> Available this week</span></div></SectionCard>
    <div className="mb-4 flex items-center justify-between"><p className="text-sm text-[hsl(var(--muted-foreground))]"><span className="font-bold text-[hsl(var(--foreground))]">{filtered.length}</span> people match your filters</p><button onClick={() => setRemote(remote === 'Remote' ? 'Any' : 'Remote')} className="flex items-center gap-1 text-xs font-bold text-[hsl(var(--primary))]" data-testid="button-toggle-remote"><Filter size={13} /> {remote === 'Remote' ? 'Remote only' : 'Sort: best match'}</button></div>
    {filtered.length ? <div className="grid gap-4 md:grid-cols-2">{filtered.map(worker => <SectionCard key={worker.id} className="group transition hover:-translate-y-1 hover:shadow-lg"><div className="flex items-start gap-4"><Avatar initials={worker.initials} color={worker.color} size="lg" /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><div><div className="flex flex-wrap items-center gap-2"><Link href={`/worker/${worker.id}`} className="text-lg font-bold hover:text-[hsl(var(--primary))]" data-testid={`link-service-worker-${worker.id}`}>{worker.name}</Link>{worker.verified && <BadgeCheck size={15} className="text-[hsl(var(--primary))]" />}</div><p className="text-sm text-[hsl(var(--muted-foreground))]">{worker.service}</p></div><button onClick={() => setFavorites(prev => prev.includes(worker.id) ? prev.filter(x => x !== worker.id) : [...prev, worker.id])} data-testid={`button-favorite-${worker.id}`}><Heart size={18} className={favorites.includes(worker.id) ? 'fill-[hsl(var(--accent))] text-[hsl(var(--accent))]' : 'text-[hsl(var(--muted-foreground))]'} /></button></div><div className="mt-3 flex flex-wrap items-center gap-3"><Rating value={worker.rating} reviews={worker.reviews} /><span className="text-xs text-[hsl(var(--muted-foreground))]">{worker.jobs} jobs</span><span className="text-xs text-[hsl(var(--muted-foreground))]">{worker.distance}</span></div><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{worker.bio}</p><div className="mt-4 flex items-center justify-between gap-3"><div className="flex flex-wrap gap-1.5">{worker.skills.map(skill => <span key={skill} className="rounded-md bg-[hsl(var(--muted))] px-2 py-1 text-[10px] font-semibold">{skill}</span>)}</div><Link href={`/worker/${worker.id}`} className="shrink-0 text-xs font-bold text-[hsl(var(--primary))]" data-testid={`link-view-profile-${worker.id}`}>View profile <ChevronRight size={13} className="inline" /></Link></div></div></div></SectionCard>)}</div> : <EmptyState title="No one matches those filters yet" copy="Try a broader category or switch between local and remote work." />}
  </div>;
}

export function Work() {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('All categories'); const [applied, setApplied] = useState<string[]>([]);
  const filtered = jobs.filter(j => (!query || `${j.title} ${j.description}`.toLowerCase().includes(query.toLowerCase())) && (category === 'All categories' || j.category === category));
  return <div className="rise-in"><PageIntro eyebrow="Marketplace / work" title="Work that fits your week." description="Fair budgets, clear briefs, and customers who respect your craft." action={<Button href="/dashboard" variant="ghost"><BarChart3 size={16} /> Your pipeline</Button>} /><SectionCard className="mb-6 p-3"><div className="grid gap-2 md:grid-cols-[1.6fr_1fr_1fr]"><label className="flex items-center gap-2 rounded-xl bg-[hsl(var(--muted)/.6)] px-3"><Search size={17} className="text-[hsl(var(--muted-foreground))]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search open briefs" className="w-full bg-transparent py-3 text-sm outline-none" data-testid="input-work-search" /></label><select value={category} onChange={e => setCategory(e.target.value)} className="rounded-xl bg-[hsl(var(--muted)/.6)] px-3 py-3 text-sm" data-testid="select-work-category"><option>All categories</option>{categories.map(c => <option key={c}>{c}</option>)}</select><select className="rounded-xl bg-[hsl(var(--muted)/.6)] px-3 py-3 text-sm" data-testid="select-work-sort"><option>Best match</option><option>Newest first</option><option>Highest budget</option></select></div></SectionCard><div className="grid gap-4">{filtered.map(job => <SectionCard key={job.id} className="transition hover:-translate-y-0.5 hover:shadow-lg"><div className="flex flex-col justify-between gap-5 md:flex-row"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Badge tone="green">{job.status}</Badge><Badge>{job.remote ? 'Remote' : 'Local'}</Badge><span className="text-xs text-[hsl(var(--muted-foreground))]">{job.posted}</span></div><Link href={`/job/${job.id}`} className="mt-3 block text-xl font-bold hover:text-[hsl(var(--primary))]" data-testid={`link-job-${job.id}`}>{job.title}</Link><p className="mt-2 max-w-2xl text-sm leading-6 text-[hsl(var(--muted-foreground))]">{job.description}</p><div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-xs text-[hsl(var(--muted-foreground))]"><span className="flex items-center gap-1"><Tag size={13} />{job.category}</span><span className="flex items-center gap-1"><MapPin size={13} />{job.location}</span><span className="flex items-center gap-1"><CalendarDays size={13} />{job.date}</span><span className="flex items-center gap-1"><Users size={13} />{job.applicants} applicants</span></div></div><div className="flex shrink-0 flex-row items-center justify-between gap-3 md:w-48 md:flex-col md:items-end"><div className="text-right"><p className="text-[10px] font-bold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Budget</p><p className="mt-1 text-lg font-bold">{job.budget}</p></div><Button onClick={() => setApplied([...applied, job.id])} variant={applied.includes(job.id) ? 'secondary' : 'primary'} testId={`button-apply-${job.id}`}>{applied.includes(job.id) ? <><Check size={15} /> Applied</> : 'Apply now'}</Button></div></div></SectionCard>)}{!filtered.length && <EmptyState title="No open briefs found" copy="Try a different keyword or browse all categories." href="/work" cta="Reset search" />}</div></div>;
}

export function Categories() {
  const [search, setSearch] = useState(''); const filtered = categories.filter(c => c.toLowerCase().includes(search.toLowerCase()));
  return <div className="rise-in"><PageIntro eyebrow="Explore the network" title="What can we get done?" description="One place for the practical, the creative, and everything between." /><label className="mb-8 flex max-w-xl items-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4"><Search size={18} className="text-[hsl(var(--muted-foreground))]" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search categories" className="w-full bg-transparent py-3.5 text-sm outline-none" data-testid="input-category-search" /></label><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{filtered.map((category, index) => <Link href={`/services?category=${encodeURIComponent(category)}`} key={category} data-testid={`link-category-${index}`} className="group flex items-center justify-between rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 transition hover:-translate-y-1 hover:border-[hsl(var(--primary)/.4)] hover:shadow-lg"><div className="flex items-center gap-4"><span className={`grid h-11 w-11 place-items-center rounded-xl ${['bg-[#d7eee4]', 'bg-[#fff0bf]', 'bg-[#f8ddd7]'][index % 3]}`}><span className="display-font text-lg font-bold text-[hsl(var(--foreground))]">{String(index + 1).padStart(2, '0')}</span></span><span className="font-bold">{category}</span></div><ArrowRight size={17} className="text-[hsl(var(--muted-foreground))] transition group-hover:translate-x-1 group-hover:text-[hsl(var(--primary))]" /></Link>)}</div></div>;
}

export function JobDetails() {
  const { id } = useParams<{ id: string }>(); const job = jobs.find(item => item.id === id) || jobs[0]; const [applied, setApplied] = useState(false); const [reported, setReported] = useState(false);
  return <div className="rise-in"><Link href="/work" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-[hsl(var(--muted-foreground))]" data-testid="link-back-work">← Back to work</Link><div className="grid gap-6 lg:grid-cols-[1fr_340px]"><div><div className="flex flex-wrap gap-2"><Badge tone="green">{job.status}</Badge><Badge>{job.remote ? 'Remote' : 'Local'}</Badge></div><h1 className="mt-5 max-w-3xl text-4xl font-bold leading-tight">{job.title}</h1><div className="mt-5 flex flex-wrap gap-4 text-sm text-[hsl(var(--muted-foreground))]"><span className="flex items-center gap-1.5"><Tag size={15} />{job.category}</span><span className="flex items-center gap-1.5"><MapPin size={15} />{job.location}</span><span className="flex items-center gap-1.5"><CalendarDays size={15} />{job.date}</span></div><SectionCard className="mt-8"><h2 className="text-lg font-bold">The brief</h2><p className="mt-3 text-sm leading-7 text-[hsl(var(--muted-foreground))]">{job.description}</p><h3 className="mt-7 text-sm font-bold">What you'll bring</h3><ul className="mt-3 space-y-3">{job.requirements.map(req => <li key={req} className="flex items-start gap-2 text-sm"><CheckCircle2 size={16} className="mt-0.5 shrink-0 text-[hsl(var(--primary))]" />{req}</li>)}</ul><div className="mt-7 border-t border-[hsl(var(--border))] pt-5"><p className="text-xs font-bold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Attachments</p><div className="mt-3 flex items-center gap-2 rounded-xl bg-[hsl(var(--muted)/.6)] p-3 text-sm"><FileText size={17} className="text-[hsl(var(--accent))]" /><span>project-notes.pdf</span><span className="ml-auto text-xs text-[hsl(var(--muted-foreground))]">1.2 MB</span></div></div></SectionCard><SectionCard className="mt-5"><div className="flex items-center justify-between"><h2 className="text-lg font-bold">Applicants <span className="ml-1 text-sm font-normal text-[hsl(var(--muted-foreground))]">{job.applicants}</span></h2><Button variant="ghost" onClick={() => setReported(!reported)}>{reported ? <Check size={15} /> : <Flag size={15} />} {reported ? 'Report received' : 'Report'}</Button></div><div className="mt-5 flex items-center gap-3"><Avatar initials="MJ" color="bg-[#e4a3a0]" /><div><p className="text-sm font-bold">Meera Joshi <BadgeCheck size={13} className="inline text-[hsl(var(--primary))]" /></p><p className="text-xs text-[hsl(var(--muted-foreground))]">₹10,000 · 2 hours ago</p></div><Rating value={4.9} /></div></SectionCard></div><aside className="space-y-5"><SectionCard className="sticky top-24"><p className="text-xs font-bold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Budget</p><p className="mt-2 text-3xl font-bold">{job.budget}</p><p className="mt-2 flex items-center gap-1.5 text-xs text-[hsl(var(--muted-foreground))]"><Clock3 size={14} /> Posted {job.posted}</p><Button onClick={() => setApplied(true)} variant={applied ? 'secondary' : 'primary'} className="mt-6 w-full" testId="button-apply-detail">{applied ? <><Check size={16} /> Application sent</> : <>Apply for this job <ArrowRight size={16} /></>}</Button><p className="mt-3 text-center text-[11px] text-[hsl(var(--muted-foreground))]">Your contact details stay private until you both agree.</p><div className="mt-6 border-t border-[hsl(var(--border))] pt-5"><p className="text-xs font-bold">Posted by</p><div className="mt-3 flex items-center gap-3"><Avatar initials="NS" color="bg-[#e4a3a0]" /><div><p className="text-sm font-bold">{job.customer}</p><p className="text-xs text-[hsl(var(--muted-foreground))]">Member since 2023 · 4 jobs posted</p></div></div></div></SectionCard><div className="rounded-2xl bg-[#d7eee4] p-5"><div className="flex gap-3"><ShieldCheck size={20} className="shrink-0 text-[#17644e]" /><div><p className="text-sm font-bold text-[#17644e]">Stay safe on KaamConnect</p><p className="mt-1 text-xs leading-5 text-[#17644e]/75">Keep conversations and payments here. Report anything that feels off.</p></div></div></div></aside></div></div>;
}

export function WorkerProfile() {
  const { id } = useParams<{ id: string }>(); const worker = workers.find(item => item.id === id) || workers[0]; const [requested, setRequested] = useState(false); const [tab, setTab] = useState('Overview');
  return <div className="rise-in"><Link href="/services" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-[hsl(var(--muted-foreground))]" data-testid="link-back-services">← Back to services</Link><div className={`rounded-[2rem] ${worker.color} p-6 sm:p-9`}><div className="flex flex-col gap-6 sm:flex-row sm:items-end"><Avatar initials={worker.initials} color="bg-[hsl(var(--card)/.75)]" size="lg" /><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h1 className="text-3xl font-bold">{worker.name}</h1>{worker.verified && <Badge tone="green"><ShieldCheck size={12} /> Verified</Badge>}</div><p className="mt-1 text-sm font-medium">{worker.service} · {worker.remote ? 'Remote friendly' : worker.radius}</p><div className="mt-4 flex flex-wrap gap-4 text-xs"><Rating value={worker.rating} reviews={worker.reviews} /><span>{worker.jobs} completed jobs</span><span className="flex items-center gap-1"><MapPin size={13} />{worker.distance}</span></div></div><Button onClick={() => setRequested(true)} variant={requested ? 'secondary' : 'primary'} testId="button-request-service">{requested ? <><Check size={15} /> Request sent</> : <>Request service <ArrowRight size={15} /></>}</Button></div></div><div className="mt-6 flex gap-6 border-b border-[hsl(var(--border))]">{['Overview', 'Reviews', 'Portfolio'].map(item => <button key={item} onClick={() => setTab(item)} className={`border-b-2 px-1 pb-3 text-sm font-bold ${tab === item ? 'border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'border-transparent text-[hsl(var(--muted-foreground))]'}`} data-testid={`button-profile-tab-${item.toLowerCase()}`}>{item}</button>)}</div>{tab === 'Overview' && <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_340px]"><div className="space-y-6"><SectionCard><h2 className="text-lg font-bold">A little about the work</h2><p className="mt-3 text-sm leading-7 text-[hsl(var(--muted-foreground))]">{worker.bio} {worker.name} keeps clients in the loop, shares a clear plan before starting, and leaves the workspace better than they found it.</p><h3 className="mt-6 text-sm font-bold">Skills</h3><div className="mt-3 flex flex-wrap gap-2">{worker.skills.map(skill => <span key={skill} className="rounded-lg bg-[hsl(var(--muted))] px-3 py-2 text-xs font-semibold">{skill}</span>)}</div></SectionCard><SectionCard><div className="flex items-center justify-between"><h2 className="text-lg font-bold">Recent work</h2><span className="text-xs text-[hsl(var(--muted-foreground))]">{worker.jobs} total</span></div><div className="mt-4 grid grid-cols-3 gap-3">{['Brand story', 'Launch cut', 'Before / after'].map((x, i) => <div key={x} className={`flex aspect-[1.25] items-end rounded-xl p-3 ${['bg-[#19343a]', 'bg-[#e4a3a0]', 'bg-[#f1c76f]'][i]}`}><span className={`text-xs font-bold ${i === 0 ? 'text-white' : 'text-[#19343a]'}`}>{x}</span></div>)}</div></SectionCard></div><aside className="space-y-5"><SectionCard><div className="flex items-start justify-between"><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Typical price</p><p className="mt-1 text-2xl font-bold">{worker.price}</p></div><WalletCards size={20} className="text-[hsl(var(--primary))]" /></div><div className="mt-5 space-y-3 border-t border-[hsl(var(--border))] pt-4 text-sm"><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Experience</span><b>{worker.experience}</b></div><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Availability</span><b>{worker.availability}</b></div><div className="flex justify-between"><span className="text-[hsl(var(--muted-foreground))]">Service area</span><b>{worker.radius}</b></div></div></SectionCard><div className="rounded-2xl border border-[hsl(var(--border))] p-5"><div className="flex gap-3"><ShieldCheck size={18} className="text-[hsl(var(--primary))]" /><div><p className="text-sm font-bold">Identity verified</p><p className="mt-1 text-xs leading-5 text-[hsl(var(--muted-foreground))]">This person has completed KaamConnect's identity and safety checks.</p></div></div></div></aside></div>}{tab === 'Reviews' && <SectionCard className="mt-6"><div className="flex items-center gap-4"><span className="display-font text-5xl font-bold">{worker.rating}</span><div><Rating value={worker.rating} /><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Based on {worker.reviews} reviews</p></div></div>{['Clear communication and beautiful final work.', 'Showed up on time and explained everything.', 'Would happily work together again.'].map((review, i) => <div key={review} className="mt-6 border-t border-[hsl(var(--border))] pt-5"><Rating value={5} /><p className="mt-2 text-sm">{review}</p><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{['Priya K.', 'Aman D.', 'Studio Nila'][i]} · verified job</p></div>)}</SectionCard>}{tab === 'Portfolio' && <SectionCard className="mt-6"><div className="grid gap-4 sm:grid-cols-3">{['Brand story', 'Launch cut', 'Before / after', 'Product edit', 'Social series', 'Event recap'].map((x, i) => <div key={x} className={`flex aspect-square items-end rounded-xl p-4 ${['bg-[#19343a]', 'bg-[#e4a3a0]', 'bg-[#f1c76f]', 'bg-[#9dbdc0]', 'bg-[#c6b2d5]', 'bg-[#b2c99c]'][i]}`}><p className={`text-sm font-bold ${i === 0 ? 'text-white' : 'text-[#19343a]'}`}>{x}</p></div>)}</div></SectionCard>}</div>;
}

export function Dashboard({ mode, onModeChange }: { mode: Mode; onModeChange: (mode: Mode) => void }) {
  const customer = mode === 'customer'; const [tab, setTab] = useState('Active');
  return <div className="rise-in"><PageIntro eyebrow={`My dashboard / ${customer ? 'customer' : 'worker'} mode`} title={customer ? 'Your work, moving forward.' : 'Your work has momentum.'} description={customer ? 'Keep every brief, conversation, and payment in one calm place.' : 'A clear view of your applications, active jobs, and what you have earned.'} action={<div className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-1"><button onClick={() => onModeChange('customer')} className={`rounded-lg px-3 py-2 text-xs font-bold ${customer ? 'bg-[hsl(var(--primary))] text-white' : ''}`} data-testid="button-dashboard-customer">Hiring</button><button onClick={() => onModeChange('worker')} className={`rounded-lg px-3 py-2 text-xs font-bold ${!customer ? 'bg-[hsl(var(--primary))] text-white' : ''}`} data-testid="button-dashboard-worker">Working</button></div>} /><div className="grid gap-3 sm:grid-cols-3">{customer ? <><StatCard label="Active briefs" value="3" detail="1 needs a reply" /><StatCard label="In progress" value="₹12,400" detail="across 2 jobs" accent="yellow" /><StatCard label="Completed" value="8 jobs" detail="₹38,600 total" accent="coral" /></> : <><StatCard label="This month" value="₹42,800" detail="+18% from May" /><StatCard label="Active jobs" value="4" detail="2 due this week" accent="yellow" /><StatCard label="Profile views" value="186" detail="+32 this week" accent="coral" /></>}</div><div className="mt-8 grid gap-6 lg:grid-cols-[1fr_340px]"><SectionCard><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">{customer ? 'Your briefs' : 'Your pipeline'}</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{customer ? 'Keep projects moving with clear next steps.' : 'Applications and active client work.'}</p></div><Button href={customer ? '/post-job' : '/work'} variant="ghost"><Plus size={15} /> {customer ? 'Post a job' : 'Find work'}</Button></div><div className="mt-5 flex gap-5 border-b border-[hsl(var(--border))]">{['Active', 'Completed'].map(x => <button onClick={() => setTab(x)} key={x} className={`pb-3 text-xs font-bold ${tab === x ? 'border-b-2 border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))]'}`} data-testid={`button-dashboard-tab-${x.toLowerCase()}`}>{x}</button>)}</div>{tab === 'Active' ? <div className="divide-y divide-[hsl(var(--border))]">{jobs.slice(0, customer ? 3 : 4).map((job, i) => <Link href={`/job/${job.id}`} key={job.id} className="flex items-center gap-3 py-4" data-testid={`link-dashboard-job-${job.id}`}><span className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${i % 2 ? 'bg-[#fff0bf]' : 'bg-[#d7eee4]'}`}><BriefcaseBusiness size={17} /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{job.title}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{job.remote ? 'Remote' : job.location} · {job.date}</p></div><span className="text-xs font-bold">{job.budget}</span><ChevronRight size={15} className="text-[hsl(var(--muted-foreground))]" /></Link>)}</div> : <EmptyState icon={CheckCircle2} title="A solid track record" copy="Completed jobs will live here once the work is wrapped." />}</SectionCard><div className="space-y-5"><SectionCard><div className="flex items-center justify-between"><h2 className="font-bold">To do next</h2><Badge tone="coral">3 items</Badge></div><div className="mt-4 space-y-3">{['Reply to Fika House', 'Upload ID verification', 'Review your profile'].map((x, i) => <button key={x} onClick={() => {}} className="flex w-full items-center gap-3 rounded-xl bg-[hsl(var(--muted)/.55)] p-3 text-left" data-testid={`button-todo-${i}`}><span className="grid h-7 w-7 place-items-center rounded-full border border-[hsl(var(--border))] text-xs font-bold">{i + 1}</span><span className="text-xs font-semibold">{x}</span><ChevronRight size={14} className="ml-auto text-[hsl(var(--muted-foreground))]" /></button>)}</div></SectionCard><div className="rounded-2xl bg-[hsl(var(--sidebar))] p-5 text-[hsl(var(--sidebar-foreground))]"><Sparkles size={20} className="text-[hsl(var(--secondary))]" /><h3 className="mt-3 font-bold">A better match is possible</h3><p className="mt-2 text-xs leading-5 text-[hsl(var(--sidebar-foreground)/.65)]">Add your service radius and availability to improve your match score.</p><Link href="/settings" className="mt-4 inline-flex items-center gap-1 text-xs font-bold text-[hsl(var(--secondary))]">Complete profile <ArrowRight size={13} /></Link></div></div></div></div>;
}

export function PostJob() {
  const [step, setStep] = useState(1); const [posted, setPosted] = useState(false); const [title, setTitle] = useState(''); const [category, setCategory] = useState('Plumber');
  if (posted) return <div className="mx-auto max-w-xl py-16 text-center rise-in"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#d7eee4] text-[#17644e]"><CheckCircle2 size={30} /></span><h1 className="mt-6 text-4xl font-bold">Your brief is live.</h1><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Good people in your area can now find it. We will let you know when someone applies.</p><div className="mt-7 flex justify-center gap-3"><Button href="/dashboard">View dashboard</Button><Button href="/work" variant="ghost">Browse work</Button></div></div>;
  return <div className="mx-auto max-w-3xl rise-in"><Link href="/" className="mb-6 inline-flex text-sm font-bold text-[hsl(var(--muted-foreground))]" data-testid="link-back-home">← Back home</Link><PageIntro eyebrow="Create a brief" title="Tell good people what you need." description="A clear brief gets better responses. You can edit anything before posting." /><div className="mb-8 flex items-center gap-2">{[1, 2, 3].map(n => <div key={n} className="flex flex-1 items-center gap-2"><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold ${step >= n ? 'bg-[hsl(var(--primary))] text-white' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]'}`}>{step > n ? <Check size={14} /> : n}</span><div className="h-1 flex-1 rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full bg-[hsl(var(--primary))] transition-all ${step > n ? 'w-full' : 'w-0'}`} /></div></div>)}</div><SectionCard>{step === 1 && <div className="space-y-5"><div><label className="text-sm font-bold">What do you need done?</label><input value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Fix leaking kitchen tap" className="mt-2 w-full rounded-xl border border-[hsl(var(--border))] bg-transparent px-4 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" data-testid="input-job-title" /></div><div><label className="text-sm font-bold">Choose a category</label><select value={category} onChange={e => setCategory(e.target.value)} className="mt-2 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-3 text-sm" data-testid="select-post-category">{categories.map(x => <option key={x}>{x}</option>)}</select></div><div><label className="text-sm font-bold">Describe the job</label><textarea rows={5} placeholder="Include the useful details: what is happening, what good looks like, and anything a worker should know." className="mt-2 w-full resize-none rounded-xl border border-[hsl(var(--border))] bg-transparent px-4 py-3 text-sm outline-none" data-testid="textarea-job-description" /></div><div className="flex items-center gap-3 rounded-xl bg-[hsl(var(--muted)/.5)] p-4"><ImagePlus size={19} className="text-[hsl(var(--primary))]" /><div className="flex-1"><p className="text-sm font-bold">Add photos or files</p><p className="text-xs text-[hsl(var(--muted-foreground))]">Optional · helps workers understand the work</p></div><Button variant="ghost"><Upload size={14} /> Add files</Button></div></div>}{step === 2 && <div className="space-y-5"><h2 className="text-xl font-bold">Make the basics clear</h2><div className="grid gap-5 sm:grid-cols-2"><label className="text-sm font-bold">Approximate location<select className="mt-2 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-3 font-normal" data-testid="select-job-location"><option>Indiranagar, Bengaluru</option><option>HSR Layout, Bengaluru</option><option>Remote / online</option></select></label><label className="text-sm font-bold">When do you need it?<input type="date" className="mt-2 w-full rounded-xl border border-[hsl(var(--border))] bg-transparent px-4 py-3 font-normal" data-testid="input-job-date" /></label></div><label className="block text-sm font-bold">Budget range<input placeholder="₹ e.g. 700 – 1,200" className="mt-2 w-full rounded-xl border border-[hsl(var(--border))] bg-transparent px-4 py-3 font-normal" data-testid="input-job-budget" /></label><div><p className="text-sm font-bold">Work mode</p><div className="mt-2 grid gap-2 sm:grid-cols-2"><button onClick={() => {}} className="rounded-xl border-2 border-[hsl(var(--primary))] bg-[#d7eee4] p-4 text-left" data-testid="button-mode-local"><House size={18} /><p className="mt-2 text-sm font-bold">In person</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Meet at an approximate location</p></button><button className="rounded-xl border border-[hsl(var(--border))] p-4 text-left" data-testid="button-mode-remote"><Laptop size={18} /><p className="mt-2 text-sm font-bold">Remote</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Work can happen online</p></button></div></div></div>}{step === 3 && <div><h2 className="text-xl font-bold">Review your brief</h2><div className="mt-5 rounded-2xl bg-[hsl(var(--muted)/.55)] p-5"><Badge tone="green">{category}</Badge><h3 className="mt-3 text-2xl font-bold">{title || 'Your job title'}</h3><div className="mt-4 grid gap-3 text-sm text-[hsl(var(--muted-foreground))] sm:grid-cols-3"><span className="flex items-center gap-2"><MapPin size={15} /> Approximate location</span><span className="flex items-center gap-2"><CalendarDays size={15} /> Flexible date</span><span className="flex items-center gap-2"><IndianRupee size={15} /> Budget added next</span></div></div><div className="mt-5 flex gap-3 rounded-xl bg-[#fff0bf] p-4 text-sm"><ShieldCheck size={19} className="shrink-0 text-[#805f08]" /><p className="text-[#805f08]">Your exact address and phone number stay hidden. Share them only after you agree on the job.</p></div></div>}<div className="mt-8 flex justify-between border-t border-[hsl(var(--border))] pt-5">{step > 1 ? <Button variant="ghost" onClick={() => setStep(step - 1)}>Back</Button> : <span />}{step < 3 ? <Button onClick={() => setStep(step + 1)} disabled={step === 1 && !title}>Continue <ArrowRight size={15} /></Button> : <Button variant="secondary" onClick={() => setPosted(true)} testId="button-post-job">Post my job <Check size={15} /></Button>}</div></SectionCard></div>;
}

export function Messages() {
  const [selected, setSelected] = useState(messages[0]); const [draft, setDraft] = useState(''); const [sent, setSent] = useState<string[]>([]);
  const submit = (e: FormEvent) => { e.preventDefault(); if (!draft.trim()) return; setSent([...sent, draft]); setDraft(''); };
  return <div className="rise-in"><PageIntro eyebrow="Keep it on platform" title="Messages" description="A safe place to align on scope, timing, and the next step. Exact addresses and phone numbers stay private." /><div className="grid min-h-[590px] overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] lg:grid-cols-[330px_1fr]"><div className="border-b border-[hsl(var(--border))] lg:border-b-0 lg:border-r"><div className="border-b border-[hsl(var(--border))] p-4"><label className="flex items-center gap-2 rounded-xl bg-[hsl(var(--muted)/.65)] px-3"><Search size={15} /><input placeholder="Search messages" className="w-full bg-transparent py-2.5 text-xs outline-none" data-testid="input-message-search" /></label></div><div>{messages.map(item => <button key={item.id} onClick={() => setSelected(item)} className={`flex w-full gap-3 border-b border-[hsl(var(--border)/.65)] p-4 text-left ${selected.id === item.id ? 'bg-[hsl(var(--muted)/.6)]' : ''}`} data-testid={`button-thread-${item.id}`}><Avatar initials={item.initials} color={item.color} /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><p className="truncate text-sm font-bold">{item.name}</p><span className="text-[10px] text-[hsl(var(--muted-foreground))]">{item.time}</span></div><p className="mt-1 truncate text-xs text-[hsl(var(--muted-foreground))]">{item.preview}</p><p className="mt-2 truncate text-[10px] text-[hsl(var(--primary))]">{item.job}</p></div>{item.unread && <span className="mt-1 h-2 w-2 rounded-full bg-[hsl(var(--accent))]" />}</button>)}</div></div><div className="flex min-h-[520px] flex-col"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] p-4"><div className="flex items-center gap-3"><Avatar initials={selected.initials} color={selected.color} /><div><p className="text-sm font-bold">{selected.name}</p><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{selected.job}</p></div></div><button className="rounded-lg p-2 text-[hsl(var(--muted-foreground))]" data-testid="button-message-options"><MoreHorizontal size={18} /></button></div><div className="flex-1 space-y-4 overflow-auto bg-[hsl(var(--muted)/.2)] p-5"><div className="mx-auto max-w-xs rounded-xl bg-[#fff0bf] px-4 py-3 text-center text-[11px] leading-5 text-[#805f08]"><LockKeyhole size={14} className="mx-auto mb-1" />Keep payments and contact details on KaamConnect.</div><div className="ml-auto max-w-[78%] rounded-2xl rounded-br-md bg-[hsl(var(--primary))] px-4 py-3 text-sm text-white"><p>Hi! Thanks for reaching out. I can share a first cut by Friday.</p><span className="mt-2 block text-right text-[10px] text-white/60">10:18 am</span></div><div className="max-w-[78%] rounded-2xl rounded-bl-md bg-[hsl(var(--card))] px-4 py-3 text-sm shadow-sm"><p>{selected.preview}</p><span className="mt-2 block text-[10px] text-[hsl(var(--muted-foreground))]">10:42 am</span></div>{sent.map((text, i) => <div key={`${text}-${i}`} className="ml-auto max-w-[78%] rounded-2xl rounded-br-md bg-[hsl(var(--primary))] px-4 py-3 text-sm text-white"><p>{text}</p><span className="mt-2 block text-right text-[10px] text-white/60">now</span></div>)}</div><form onSubmit={submit} className="flex items-center gap-2 border-t border-[hsl(var(--border))] p-4"><button type="button" className="rounded-lg p-2 text-[hsl(var(--muted-foreground))]" data-testid="button-attach-message"><Paperclip size={18} /></button><input value={draft} onChange={e => setDraft(e.target.value)} placeholder="Write a message..." className="flex-1 bg-transparent text-sm outline-none" data-testid="input-message-draft" /><button type="submit" className="grid h-9 w-9 place-items-center rounded-xl bg-[hsl(var(--primary))] text-white" data-testid="button-send-message"><Send size={16} /></button></form></div></div></div>;
}

export function Earnings() {
  const [withdrawn, setWithdrawn] = useState(false);
  return <div className="rise-in"><PageIntro eyebrow="Worker tools" title="Money, made clear." description="See what is earned, what is pending, and exactly how the 10% platform commission works." action={<Button onClick={() => setWithdrawn(true)} variant={withdrawn ? 'secondary' : 'primary'}><WalletCards size={16} /> {withdrawn ? 'Payout requested' : 'Request payout'}</Button>} /><div className="grid gap-3 sm:grid-cols-3"><StatCard label="Available to withdraw" value="₹38,520" detail="Next payout: instant" /><StatCard label="Pending" value="₹12,400" detail="2 jobs in progress" accent="yellow" /><StatCard label="Total earned" value="₹2,84,670" detail="Since Jan 2024" accent="coral" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_360px]"><SectionCard><div className="flex items-center justify-between"><h2 className="text-lg font-bold">Recent payments</h2><Button variant="ghost">Download report <FileText size={14} /></Button></div><div className="mt-4 divide-y divide-[hsl(var(--border))]">{[['Website audit · Mitra Clinic', '₹9,000', 'Jun 12', 'Paid'], ['Brand reels · Fika House', '₹14,400', 'Jun 03', 'Paid'], ['Math tutoring · Aanya R.', '₹3,600', 'May 29', 'Paid'], ['Logo design · Paper Boat', '₹6,200', 'May 18', 'Paid']].map(([name, amount, date, status]) => <div key={name} className="flex items-center gap-3 py-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#d7eee4]"><IndianRupee size={15} className="text-[#17644e]" /></span><div className="flex-1"><p className="text-sm font-bold">{name}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{date} · {status}</p></div><div className="text-right"><p className="text-sm font-bold">{amount}</p><p className="mt-1 text-[10px] text-[hsl(var(--primary))]">+ credited</p></div></div>)}</div></SectionCard><div className="space-y-5"><SectionCard className="bg-[hsl(var(--sidebar))] text-[hsl(var(--sidebar-foreground))]"><div className="flex items-center justify-between"><h2 className="font-bold">On a ₹10,000 job</h2><IndianRupee size={18} className="text-[hsl(var(--secondary))]" /></div><div className="mt-6 space-y-4 text-sm"><div className="flex justify-between text-[hsl(var(--sidebar-foreground)/.65)]"><span>Client pays</span><span>₹10,000</span></div><div className="flex justify-between text-[hsl(var(--sidebar-foreground)/.65)]"><span>KaamConnect commission</span><span>− ₹1,000</span></div><div className="border-t border-[hsl(var(--sidebar-border))] pt-4 flex justify-between font-bold"><span>You receive</span><span className="text-[hsl(var(--secondary))]">₹9,000</span></div></div><p className="mt-5 text-xs leading-5 text-[hsl(var(--sidebar-foreground)/.55)]">That 10% keeps payments protected, profiles verified, and support human.</p></SectionCard><SectionCard><h2 className="font-bold">Payout account</h2><div className="mt-4 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-lg bg-[hsl(var(--muted))]"><BuildingIcon /></span><div><p className="text-sm font-bold">HDFC Bank · •• 4821</p><p className="text-xs text-[hsl(var(--muted-foreground))]">Verified account</p></div><button className="ml-auto text-[hsl(var(--primary))]" data-testid="button-edit-payout"><Pencil size={15} /></button></div></SectionCard></div></div></div>;
}
